--
-- Table structure for table `batches`
--

DROP TABLE IF EXISTS `batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `batches` (
  `batch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'BATCH-YYYYMM-NNN',
  `batch_no` int NOT NULL,
  `batch_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `model_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Single model per batch',
  `major_category` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `base_capacity` int DEFAULT NULL,
  `capacity_override` int DEFAULT NULL,
  `capacity` int NOT NULL COMMENT 'G/XS=30, AUTO=27',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Predicted' COMMENT 'Predicted / Confirmed / In_Production / Completed',
  `due_date_start` date DEFAULT NULL,
  `due_date_end` date DEFAULT NULL,
  `expected_inbound_date` date DEFAULT NULL,
  `capacity_snapshot` json DEFAULT NULL COMMENT 'Capacity ratio snapshot at generation',
  `source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'algorithm' COMMENT 'algorithm / manual',
  `production_line_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`batch_id`) USING BTREE,
  KEY `idx_batches_status` (`status`) USING BTREE,
  KEY `idx_batches_model` (`model_type`) USING BTREE,
  KEY `idx_batches_line` (`production_line_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

